<script>
import * as echarts from 'echarts';
import axios from 'axios';

export default {
  name: 'Evaluation',
  data() {
    return {
      radarIndicator: [],
      radarData: [],
      // 接收从Home.vue传递过来的13个参数
      question: this.$route.query.question || '',
      user_response: this.$route.query.user_response || '',
      bot_response: this.$route.query.bot_response || '',
      user_answer: this.$route.query.user_answer || '',
      subtitle: this.$route.query.subtitle || '',
      role: this.$route.query.role || '',
      scenario: this.$route.query.scenario || '',
      emotion: this.$route.query.emotion || '',
      relationship: this.$route.query.relationship || '',
      goal: this.$route.query.goal || '',
      style: this.$route.query.style || '',
      quit: this.$route.query.quit || 1,
      qa_ref_id: this.$route.query.qa_ref_id || '',
      evaluationReasons: ['', '', '', '', ''], // 存储5个维度的评分理由
      isLoading: true, // 添加加载状态
      suggestion: '' // 新增建议字段
    }
  },
  mounted() {
    // 输出接收到的参数用于调试
    console.log('evaluation.vue 接收到的参数:', {
      question: this.question,
      user_response: this.user_response,
      bot_response: this.bot_response,
      user_answer: this.user_answer,
      subtitle: this.subtitle,
      role: this.role,
      scenario: this.scenario,
      emotion: this.emotion,
      relationship: this.relationship,
      goal: this.goal,
      style: this.style,
      quit: this.quit,
      qa_ref_id: this.qa_ref_id
    });
    
    this.getRadarData();
  },
  methods: {
    async getRadarData() {
      this.isLoading = true; // 开始加载
      try {
        const res = await this.axios.post('http://dify.ai-role.cn/v1/chat-messages', {
          query: 'get evaluation',
          inputs: {
              question: this.question,
              user_response: this.user_response,
              bot_response: this.bot_response,
              user_answer: this.user_answer,
              subtitle: this.subtitle,
              role: this.role,
              scenario: this.scenario,
              emotion: this.emotion,
              relationship: this.relationship,
              goal: this.goal,
              style: this.style,
              quit: this.quit
            },
          response_mode: "blocking",
          user: "abc-123",
          conversation_id: this.qa_ref_id
        }, {
          headers: {
            'Authorization': 'Bearer app-UWsg0s0Czom9yAvk9oekWOkT',
            'Content-Type': 'application/json'
          }
        });
        console.log(res);
        const data = res.data.answer || '';
        console.log('雷达图数据:', data);
        
        // 解析返回的字符串格式数据
        this.parseEvaluationData(data);
        // 等待DOM更新后再初始化雷达图
        this.$nextTick(() => {
          this.initRadarChart();
        });
      } catch (e) {
        console.error('获取雷达图数据失败:', e);
        // 请求失败时用默认数据
        this.radarIndicator = [
          { name: '情绪识别', max: 5 },
          { name: '心理推理', max: 5 },
          { name: '行为预测', max: 5 },
          { name: '策略调整', max: 5 },
          { name: '情绪调节', max: 5 }
        ];
        this.radarData = [2, 2, 2, 2, 2];
        this.evaluationReasons = [
          '默认评分理由：情绪识别表现良好',
          '默认评分理由：心理推理得当',
          '默认评分理由：行为预测稳定',
          '默认评分理由：策略调整清晰',
          '默认评分理由：情绪调节有效'
        ];
        this.suggestion = '建议：尝试表达自己的感受和理由，并提出具体承诺或改进措施，促进建设性对话。';
        // 等待DOM更新后再初始化雷达图
        this.$nextTick(() => {
          this.initRadarChart();
        });
      } finally {
        this.isLoading = false; // 结束加载
      }
    },
    parseEvaluationData(data) {
      // 动态设置雷达图维度，从返回数据中提取
      this.radarIndicator = [];
      this.radarData = [];
      this.evaluationReasons = ['', '', '', '', ''];
      
      // 解析评分部分：1.情绪识别：x
      const scorePattern = /(\d+)\.\s*([^：]+)：\s*(\d+)/g;
      let match;
      console.log('开始解析评分数据，原始数据:', data);
      console.log('使用的正则表达式:', scorePattern);
      
      while ((match = scorePattern.exec(data)) !== null) {
        const dimensionName = match[2].trim();
        const score = parseInt(match[3]);
        console.log(`匹配到维度: ${dimensionName}, 分数: ${score}`);
        
        // 动态添加维度
        this.radarIndicator.push({ name: dimensionName, max: 5 });
        this.radarData.push(score);
      }
      
      // 确保至少有5个维度
      while (this.radarIndicator.length < 5) {
        this.radarIndicator.push({ name: `维度${this.radarIndicator.length + 1}`, max: 5 });
        this.radarData.push(0);
      }
      
      // 只取前5个维度
      this.radarIndicator = this.radarIndicator.slice(0, 5);
      this.radarData = this.radarData.slice(0, 5);
      
      console.log('解析后的维度数组:', this.radarIndicator);
      console.log('解析后的分数数组:', this.radarData);
      // 解析评分理由部分
      // 1. 找到"评分理由："后面的内容
      const reasonStart = data.indexOf('评分理由：');
      console.log('评分理由开始位置:', reasonStart);
      
      if (reasonStart !== -1) {
        // 找到"建议："或"改进建议："的位置，用于分割理由和建议
        const suggestionStart = data.indexOf('建议：');
        const improvementStart = data.indexOf('改进建议：');
        let reasonEnd = data.length;
        
        if (suggestionStart !== -1 && suggestionStart > reasonStart) {
          reasonEnd = suggestionStart;
        } else if (improvementStart !== -1 && improvementStart > reasonStart) {
          reasonEnd = improvementStart;
        }
        
        let reasonText = data.slice(reasonStart + 5, reasonEnd).trim();
        console.log('提取的评分理由文本:', reasonText);
        
        // 2. 用更准确的正则表达式分割出每一条理由
        // 匹配"1. 情绪识别：xxxxx" 或 "1. xxxxx" 格式
        const reasonPattern = /(\d+)\.\s*([^：\n]+：)?\s*([^\n]+)/g;
        let reasonMatch;
        let reasonIndex = 0;
        
        while ((reasonMatch = reasonPattern.exec(reasonText)) !== null && reasonIndex < 5) {
          const fullMatch = reasonMatch[0]; // 完整匹配
          const number = reasonMatch[1]; // 编号
          const dimensionName = reasonMatch[2] || ''; // 维度名（可能没有）
          const reasonContent = reasonMatch[3] || ''; // 理由内容
          
          console.log(`理由匹配${reasonIndex + 1}:`, {
            fullMatch,
            number,
            dimensionName,
            reasonContent
          });
          
          // 如果理由内容包含维度名，去掉维度名部分
          let cleanReason = reasonContent.trim();
          if (dimensionName) {
            // 去掉维度名和冒号
            cleanReason = reasonContent.replace(dimensionName, '').trim();
          }
          
          // 如果理由内容以冒号开头，去掉冒号
          if (cleanReason.startsWith('：')) {
            cleanReason = cleanReason.substring(1).trim();
          }
          
          console.log(`清理后的理由${reasonIndex + 1}:`, cleanReason);
          this.evaluationReasons[reasonIndex] = cleanReason;
          reasonIndex++;
        }
      }
      // 解析建议部分
      console.log('开始解析建议部分...');
      const suggestionStart = data.indexOf('改进建议：');
      console.log('改进建议开始位置:', suggestionStart);
      
      if (suggestionStart !== -1) {
        this.suggestion = data.slice(suggestionStart + 5).trim();
        console.log('提取的建议内容:', this.suggestion);
      } else {
        // 尝试其他格式的建议提取
        const suggestionPatterns = [
          /改进建议：\s*(.+?)(?=\n\d+\.|$)/s,
          /建议：\s*(.+?)(?=\n\d+\.|$)/s,
          /建议\s*(.+?)(?=\n\d+\.|$)/s
        ];
        
        for (const pattern of suggestionPatterns) {
          const match = data.match(pattern);
          if (match) {
            this.suggestion = match[1].trim();
            console.log('通过正则匹配到的建议:', this.suggestion);
            break;
          }
        }
        
        // 如果还是没找到，尝试提取最后一个段落作为建议
        if (!this.suggestion) {
          const lines = data.split('\n').filter(line => line.trim());
          const lastLine = lines[lines.length - 1];
          if (lastLine && !lastLine.match(/^\d+\./)) {
            this.suggestion = lastLine.trim();
            console.log('提取的最后一行作为建议:', this.suggestion);
          }
        }
      }
      // 兜底：如果有空理由，填充默认
      this.evaluationReasons = this.evaluationReasons.map((r, i) => r || `暂无评分理由`);
      // 控制台输出调试
      console.log('解析后的雷达图数据:', {
        indicator: this.radarIndicator,
        data: this.radarData,
        reasons: this.evaluationReasons
      });
    },
    initRadarChart() {
      const chartDom = document.getElementById('radarChart');
      if (!chartDom) {
        console.warn('雷达图DOM元素不存在，跳过初始化');
        return;
      }
      
      console.log('初始化雷达图，数据:', {
        indicator: this.radarIndicator,
        data: this.radarData
      });
      
      const myChart = echarts.init(chartDom);
      const option = {
        tooltip: {},
        radar: {
          indicator: this.radarIndicator,
          splitLine: {
            lineStyle: {
              color: '#e0d7f7',
            }
          },
          splitArea: {
            areaStyle: {
              color: ['#f6f0ff', '#f3eaff'],
            }
          },
          axisLine: {
            lineStyle: {
              color: '#a084e8',
            }
          },
          name: {
            color: '#a084e8',
            fontSize: 16
          }
        },
        series: [{
          name: '得分',
          type: 'radar',
          areaStyle: {
            color: 'rgba(160, 132, 232, 0.3)'
          },
          lineStyle: {
            color: '#a084e8',
            width: 3
          },
          itemStyle: {
            color: '#a084e8',
            borderColor: '#fff',
            borderWidth: 2
          },
          data: [
            {
              value: this.radarData,
              name: '样例',
              areaStyle: {
                color: 'rgba(160, 132, 232, 0.3)'
              },
              lineStyle: {
                color: '#a084e8',
                width: 3
              },
              itemStyle: {
                color: '#a084e8',
                borderColor: '#fff',
                borderWidth: 2
              }
            }
          ]
        }]
      };
      myChart.setOption(option);
    }
  }
}
</script>