  methods: {
    async sendMessage() {
      // 若用户未完成对话设置，则统一回复提示语
      if (!this.settingsConfirmed) {
        const text = this.input && this.input.trim();
        if (!text || this.loading) return;
        this.messages.push({ role: 'user', text });
        this.input = '';
        const tip = '你好，你可以先在右上角设置对话场景，设置完成后可以和我进行聊天！';
        this.messages.push({ role: 'bot', text: tip });
        this.lastBotMessage = tip;
        this.$nextTick(() => {
          const chatHistory = this.$el.querySelector('.chat-history');
          if (chatHistory) chatHistory.scrollTop = chatHistory.scrollHeight;
        });
        return;
      }
      const text = this.input && this.input.trim();
      if (!text || this.loading) return;
      const isCustom = this.currentTitle === '自定义场景';
      const inputsPayload = {
       
      };
      if (isCustom) {
        inputsPayload.role = (this.customRole || '').trim();
        inputsPayload.relationship = (this.customRelation || '').trim();
        inputsPayload.scenario = (this.customScene || '').trim();
        inputsPayload.emotion = (this.customEmotion || '').trim();
        inputsPayload.goal = (this.customGoal || '').trim();
        inputsPayload.style = (this.customStyle || '').trim();
      } else {
        // 从预设中找到并发送详细信息
        const preset = this.scenePresets.find(p => p.name === this.currentTitle);
        if (preset) {
          inputsPayload.role = preset.role;
          inputsPayload.relationship = preset.relationship;
          inputsPayload.scenario = preset.scenario;
          inputsPayload.emotion = preset.emotion;
          inputsPayload.goal = preset.goal;
          inputsPayload.style = preset.style;
        } else {
          inputsPayload.title = this.currentTitle;
        }
      }
      this.lastInputsPayload = { ...inputsPayload };
      const titleForFeedback = this.currentTitle;
      console.log(this.currentTitle);
      this.messages.push({ role: 'user', text });
      this.lastUserMessage = text;
      this.input = '';
      this.loading = true;
      this.$nextTick(() => {
        const chatHistory = this.$el.querySelector('.chat-history');
        if (chatHistory) chatHistory.scrollTop = chatHistory.scrollHeight;
      });
      // 先插入一个空的机器人气泡
      const botMsg = { role: 'bot', text: '' };
      this.messages.push(botMsg);
      this.$nextTick(() => {
        const chatHistory = this.$el.querySelector('.chat-history');
        if (chatHistory) chatHistory.scrollTop = chatHistory.scrollHeight;
      });
      let botResponse = '';
      console.log(inputsPayload);
      try {
        const response = await fetch('http://dify.ai-role.cn/v1/chat-messages', {
          method: 'POST',
          headers: {
            'Authorization': 'Bearer app-TzV97h4LUJkvWwSfDL4xS0Og',
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({
            query: text,
            inputs: inputsPayload,
            response_mode: "streaming",
            user: "abc-123",
            conversation_id:this.conversation_id
          })
        });
        if (!response.body || !window.ReadableStream) {
          // fallback: 不是流式响应
          const data = await response.json();
          botMsg.text = data.answer || data.response || '（大模型无回复）';
          botResponse = botMsg.text;
          this.lastBotMessage = botResponse;
          
          // 获取conversation_id
          if (data.conversation_id) {
            this.conversation_id = data.conversation_id;
          }
          
          this.loading = false;
          // 机器人回复后，拉取反馈与动态QA
          this.get_score_feedback(titleForFeedback, text, botResponse);
          this.get_teach_feedback(titleForFeedback, text, botResponse);
          this.get_qa_questions(titleForFeedback, text, botResponse);
          return;
        }
        const reader = response.body.getReader();
        // console.log(response);
        const decoder = new TextDecoder('utf-8');
        let done = false;
        let buffer = '';
        // let conversationIdReceived = false;
        
        while (!done) {
          const { value, done: doneReading } = await reader.read();
          done = doneReading;
          if (value) {
            buffer += decoder.decode(value, { stream: true });
            // 以换行分割流式片段
            let lines = buffer.split('\n');
            buffer = lines.pop();
            for (const line of lines) {
              if (!line.trim()) continue;
              if (line.startsWith('event: ping')) continue; // 跳过心跳包
              // 兼容 SSE 格式: data: xxx
              let content = line;
              if (line.startsWith('data:')) content = line.replace(/^data:\s*/, '');
              try {
                const json = JSON.parse(content);
                if (json.answer) {
                  botMsg.text += json.answer;
                } else if (json.response) {
                  botMsg.text += json.response;
                } else if (typeof json === 'string') {
                  botMsg.text += json;
                }
                // console.log(json);
                this.conversation_id = json.conversation_id;
                // 获取conversation_id（只在第一次收到时设置）
                // if (!conversationIdReceived && json.conversation_id) {
                //   this.conversation_id = json.conversation_id;
                //   conversationIdReceived = true;
                // }
              } catch {
                botMsg.text += content;
              }
              this.$forceUpdate();
              this.$nextTick(() => {
                const chatHistory = this.$el.querySelector('.chat-history');
                if (chatHistory) chatHistory.scrollTop = chatHistory.scrollHeight;
              });
            }
          }
        }
        // 处理最后一段
        if (buffer && buffer.trim()) {
          try {
            const json = JSON.parse(buffer);
            if (json.answer) {
              botMsg.text += json.answer;
            } else if (json.response) {
              botMsg.text += json.response;
            } else if (typeof json === 'string') {
              botMsg.text += json;
            }
          } catch {
            botMsg.text += buffer;
          }
          this.$forceUpdate();
        }
        botResponse = botMsg.text;
        this.lastBotMessage = botResponse;
      } catch (e) {
        console.error('API请求错误:', e);
        botMsg.text = '机器人服务暂时不可用，请稍后再试。';
        botResponse = botMsg.text;
      } finally {
        this.loading = false;
        // 机器人回复后，拉取动态QA（流式结束后兜底再拉一次）
        console.log(botResponse);
        this.get_qa_questions(titleForFeedback, text, botResponse);
       }
    },
    prevQuestion() {
      if (this.currentQaIndex > 0) {
        this.currentQaIndex--;
        console.log('切换到上一题，当前索引:', this.currentQaIndex);
