    submitCurrentAnswer() {
      // 安全检查：确保数组存在且有足够的长度
      if (!this.qaAnswers || this.qaAnswers.length < 4) {
        console.error('qaAnswers数组长度不足:', this.qaAnswers?.length);
        return;
      }
      
      if (!this.qaSubmitted || this.qaSubmitted.length < 4) {
        console.error('qaSubmitted数组长度不足:', this.qaSubmitted?.length);
        return;
      }
      
      if (!this.qaRefLoading || this.qaRefLoading.length < 4) {
        console.error('qaRefLoading数组长度不足:', this.qaRefLoading?.length);
        return;
      }
      
      if (this.qaAnswers[this.currentQaIndex]) {
        // 标记当前题目已提交，显示参考答案
        this.$set(this.qaSubmitted, this.currentQaIndex, true);
        this.$set(this.qaRefLoading, this.currentQaIndex, true);
        console.log('提交当前答案:', this.qaAnswers[this.currentQaIndex]);
        console.log('当前题目索引:', this.currentQaIndex);
        console.log('数组状态:', {
          qaAnswers: this.qaAnswers.length,
          qaSubmitted: this.qaSubmitted.length,
          qaRefLoading: this.qaRefLoading.length
        });
        
        // 动态获取参考答案
        const question = this.qaQuestions[this.currentQaIndex] || '';
        const answer = this.qaAnswers[this.currentQaIndex] || '';
        this.get_qa_reference(question, answer, this.lastUserMessage, this.lastBotMessage);
