    async get_teach_feedback(title, user_response, bot_response) {
      this.teachFeedbackLoading = true; // 新增
      // console.log(this.teach_id)
      try {
        const res = await axios.post('http://dify.ai-role.cn/v1/chat-messages', {
          query: 'teach feedback',
          inputs: {
            title: title,
            user_response: user_response,
            bot_response: bot_response
          },
          response_mode: "blocking",
          user: "abc-123",
          conversation_id:this.teach_id
        }, {
          headers: {
            'Authorization': 'Bearer app-YhRXu8JFuHs9deDyR8AJwYrC',
            'Content-Type': 'application/json'
          }
        });
        // 假设返回字符串 answer
        const str = res.data.answer || '';
        console.log('教学反馈原始数据:', res.data.answer);
        this.teach_id=res.data.conversation_id;
        // 分割字符串为4个卡片
        const cardDefs = [
          { title: 'NVC', icon: '💡', colorClass: 'teach-yellow' },
          { title: 'Proposal', icon: '⭐', colorClass: 'teach-green' },
          { title: 'Concession', icon: '💡', colorClass: 'teach-blue' },
          { title: 'Promise', icon: '⭐', colorClass: 'teach-purple' }
        ];
        
        // 尝试多种匹配方式
        let result = [];
        
        // 方式1: 使用正则表达式匹配
        const regex = /(NVC|Proposal|Concession|Promise)：(.*?)(?=(NVC|Proposal|Concession|Promise)：|$)/gs;
        let match;
        while ((match = regex.exec(str)) !== null) {
          const idx = cardDefs.findIndex(c => c.title === match[1]);
          if (idx !== -1) {
            result[idx] = {
              ...cardDefs[idx],
              content: match[2].trim()
            };
          }
        }
        
        // 方式2: 如果正则匹配失败，尝试按行分割
        if (result.length === 0) {
          const lines = str.split('\n').filter(line => line.trim());
          lines.forEach(line => {
            const colonIndex = line.indexOf('：');
            if (colonIndex > 0) {
              const title = line.substring(0, colonIndex).trim();
              const content = line.substring(colonIndex + 1).trim();
              const idx = cardDefs.findIndex(c => c.title === title);
              if (idx !== -1) {
                result[idx] = {
                  ...cardDefs[idx],
                  content: content
                };
              }
            }
          });
        }
        
        console.log('解析后的教学反馈:', result);
        
        // 保证顺序和完整性
        this.teachFeedback = cardDefs.map((def, i) => result[i] || { ...def, content: '暂无反馈内容' });
        console.log(this.teachFeedback)
      } catch (e) {
        this.teachFeedback = [];
      } finally {
        this.teachFeedbackLoading = false; // 新增
      }
    },
    async get_qa_questions(title, user_response, bot_response) {
      this.qaLoading = true;
      try {
        const res = await axios.post('http://dify.ai-role.cn/v1/chat-messages', {
          query: 'qa questions',
          inputs: {
            user_response: user_response,
            bot_response: bot_response,
            subtitle: this.qaTitles[this.currentQaIndex],
            role: this.lastInputsPayload.role || '',
            scenario: this.lastInputsPayload.scenario || '',
            emotion: this.lastInputsPayload.emotion || '',
            relationship: this.lastInputsPayload.relationship || '',
            goal: this.lastInputsPayload.goal || '',
            style: this.lastInputsPayload.style || ''
          },
          response_mode: "blocking",
          user: "abc-123",
          conversation_id: this.qa_id
        }, {
          headers: {
            'Authorization': 'Bearer app-w9eF61flgZ4PzdiFgjcG6DMP',
            'Content-Type': 'application/json'
          }
        });
        
        const str = res.data.answer || '';
        this.qa_id = res.data.conversation_id || this.qa_id;
        
        console.log('API返回的原始问题数据:', str);
        
        // 解析出4个问题：提取冒号后面的内容
        let questions = [];
        
        // 方法1: 使用正则表达式匹配数字编号格式
        const regex = /(\d+)\.\s*[^：]*：\s*(.*)/g;
        let match;
        while ((match = regex.exec(str)) !== null) {
          const text = (match[2] || '').trim();
          if (text) {
            questions.push(text);
            console.log(`正则匹配到问题${questions.length}:`, text);
          }
        }
        
        // 方法2: 如果正则匹配失败，尝试按行分割并提取冒号后内容
        if (questions.length === 0) {
          console.log('正则匹配失败，尝试按行分割...');
          const lines = str.split('\n').map(s => s.trim()).filter(Boolean);
          console.log('分割后的行数:', lines.length);
          
          for (const line of lines) {
            const colonIndex = line.indexOf('：');
            if (colonIndex > 0) {
              const content = line.substring(colonIndex + 1).trim();
              if (content) {
                questions.push(content);
                console.log(`行分割匹配到问题${questions.length}:`, content);
              }
            }
          }
        }
        
        // 方法3: 如果还是失败，尝试更宽松的匹配
        if (questions.length === 0) {
          console.log('行分割也失败，尝试更宽松的匹配...');
          const lines = str.split('\n').map(s => s.trim()).filter(Boolean);
          
          for (const line of lines) {
            // 尝试匹配各种分隔符
            let content = '';
            if (line.includes('：')) {
              content = line.split('：')[1]?.trim();
            } else if (line.includes(':')) {
              content = line.split(':')[1]?.trim();
            } else if (line.includes('.')) {
              content = line.split('.')[1]?.trim();
            } else if (line.includes('、')) {
              content = line.split('、')[1]?.trim();
            }
            
            if (content && content.length > 5) { // 确保内容有足够长度
              questions.push(content);
              console.log(`宽松匹配到问题${questions.length}:`, content);
            }
          }
        }
        
        console.log('最终解析到的问题数量:', questions.length);
        console.log('解析到的问题:', questions);
        
        // 如果不足4条，补足为4条
        while (questions.length < 4) {
          const defaultQuestion = `请根据对话补充问题${questions.length + 1}`;
          questions.push(defaultQuestion);
          console.log(`补充默认问题${questions.length}:`, defaultQuestion);
        }
        
        // 确保只取前4个问题
        this.qaQuestions = questions.slice(0, 4);
        console.log('最终设置的问题数组:', this.qaQuestions);
        console.log('问题数组长度:', this.qaQuestions.length);
        
        // 重置作答状态
        this.currentQaIndex = 0;
        this.qaAnswers = new Array(4).fill(''); // 确保有4个空字符串
        this.qaSubmitted = new Array(4).fill(false); // 确保有4个false
        this.qaRefLoading = new Array(4).fill(false); // 确保有4个false
        this.qaFinished = false;
        
        // 验证数组长度
        console.log('验证数组长度:');
        console.log('qaQuestions长度:', this.qaQuestions.length);
        console.log('qaAnswers长度:', this.qaAnswers.length);
        console.log('qaSubmitted长度:', this.qaSubmitted.length);
        console.log('qaRefLoading长度:', this.qaRefLoading.length);
        
      } catch (e) {
        // 请求失败时不改变现有问题
        console.error('获取动态问题失败:', e);
      } finally {
        this.qaLoading = false;
      }
    },
